#include <USB.h>
#include <USBHIDKeyboard.h>
#include <USBHIDMouse.h>

USBHIDKeyboard Keyboard;
USBHIDMouse Mouse;

// ======== матрица 4x4 ========
const int ROW_PINS[4] = {13, 12, 11, 10};  // строки
const int COL_PINS[4] = {9, 8, 7, 6};      // столбцы

// коды клавиш
enum {
  K_Q, K_W, K_E, K_LMB,
  K_A, K_S, K_D, K_RMB,
  K_C, K_CUP, K_SPC, K_SHIFT,
  K_CLEFT, K_CDOWN, K_CRIGHT, K_ESC
};

const char* KEY_NAMES[16] = {
  "Q", "W", "E", "ЛКМ",
  "A", "S", "D", "ПКМ",
  "C", "Камера вверх", "Пробел", "Shift",
  "Камера влево", "Камера вниз", "Камера вправо", "ESC"
};

// ======== состояние ========
bool pressed[16] = {false};
bool wasPressed[16] = {false};

// ======== настройки камеры ========
const int CAM_STEP = 1;            // пикселей за шаг (меньше = плавнее)
const int CAM_INTERVAL = 15;       // мс между шагами (больше = медленнее)
unsigned long lastCamMove = 0;

// ======== сканирование всей матрицы ========
void scanMatrix() {
  for (int i = 0; i < 16; i++) wasPressed[i] = pressed[i];

  for (int c = 0; c < 4; c++) {
    pinMode(COL_PINS[c], OUTPUT);
    digitalWrite(COL_PINS[c], LOW);
    for (int r = 0; r < 4; r++) {
      pinMode(ROW_PINS[r], INPUT_PULLUP);
      int idx = r * 4 + c;
      pressed[idx] = (digitalRead(ROW_PINS[r]) == LOW);
      pinMode(ROW_PINS[r], INPUT);
    }
    pinMode(COL_PINS[c], INPUT);
  }
}

// ======== нажатие/отпускание ========
void keyDown(int k) {
  switch (k) {
    case K_Q:  Keyboard.press('q'); break;
    case K_W:  Keyboard.press('w'); break;
    case K_E:  Keyboard.press('e'); break;
    case K_A:  Keyboard.press('a'); break;
    case K_S:  Keyboard.press('s'); break;
    case K_D:  Keyboard.press('d'); break;
    case K_C:  Keyboard.press('c'); break;
    case K_SPC:   Keyboard.press(' '); break;
    case K_SHIFT: Keyboard.press(KEY_LEFT_SHIFT); break;
    case K_ESC:   Keyboard.press(KEY_ESC); break;
    case K_LMB:   Mouse.press(MOUSE_LEFT); break;
    case K_RMB:   Mouse.press(MOUSE_RIGHT); break;
  }
  Serial.print("Нажата: ");
  Serial.println(KEY_NAMES[k]);
}

void keyUp(int k) {
  switch (k) {
    case K_Q:  Keyboard.release('q'); break;
    case K_W:  Keyboard.release('w'); break;
    case K_E:  Keyboard.release('e'); break;
    case K_A:  Keyboard.release('a'); break;
    case K_S:  Keyboard.release('s'); break;
    case K_D:  Keyboard.release('d'); break;
    case K_C:  Keyboard.release('c'); break;
    case K_SPC:   Keyboard.release(' '); break;
    case K_SHIFT: Keyboard.release(KEY_LEFT_SHIFT); break;
    case K_ESC:   Keyboard.release(KEY_ESC); break;
    case K_LMB:   Mouse.release(MOUSE_LEFT); break;
    case K_RMB:   Mouse.release(MOUSE_RIGHT); break;
  }
}

// плавный просмотр: пока кнопка держится — шагаем каждый CAM_INTERVAL мс
void handleCamera(int k, int dx, int dy) {
  if (!pressed[k]) return;
  if (millis() - lastCamMove < CAM_INTERVAL) return;
  lastCamMove = millis();
  Mouse.move(dx, dy);
}

void setup() {
  Serial.begin(115200);

  USB.begin();
  Keyboard.begin();
  Mouse.begin();
  delay(2000);
  Serial.println("Minecraft keypad ready");
}

void loop() {
  scanMatrix();

  for (int i = 0; i < 16; i++) {
    if (pressed[i] && !wasPressed[i]) keyDown(i);   // только что нажали
    if (!pressed[i] && wasPressed[i]) keyUp(i);     // только что отпустили
  }

  // камеры — плавный дрейф, пока кнопка удерживается
  handleCamera(K_CUP,    0, -CAM_STEP);
  handleCamera(K_CDOWN,  0,  CAM_STEP);
  handleCamera(K_CLEFT, -CAM_STEP, 0);
  handleCamera(K_CRIGHT, CAM_STEP, 0);

  delay(3);
}
